#include <string>
#include <algorithm>
using namespace std;

int main() {
    string s1 = "Hello", s2 = " World";
    // Concatenation
    string s3 = s1 + s2;
    cout << s3 << endl;           // Hello World
    // Substring
    cout << s3.substr(6, 5) << endl; // World
    // Find
    cout << s3.find("World") << endl; // 6
    // Reverse
    string rev = s1;
    reverse(rev.begin(), rev.end());
    cout << rev << endl;          // olleH
    // Compare
    cout << (s1 == "Hello" ? "equal" : "not equal") << endl;
    return 0;
}

