#include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<int> computeLPS(const string& pat) {
    int m = pat.size();
    vector<int> lps(m, 0);
    int len = 0, i = 1;
    while (i < m) {
        if (pat[i] == pat[len]) { lps[i++] = ++len; }
        else if (len) { len = lps[len-1]; }
        else { lps[i++] = 0; }
    }
    return lps;
}

void kmpSearch(const string& text, const string& pat) {
    int n = text.size(), m = pat.size();
    vector<int> lps = computeLPS(pat);
    int i = 0, j = 0;
    while (i < n) {
        if (text[i] == pat[j]) { i++; j++; }
        if (j == m) { cout << "Pattern at index " << i-j << endl; j = lps[j-1]; }
        else if (i < n && text[i] != pat[j]) {
            if (j) j = lps[j-1]; else i++;
        }
    }
}

int main() {
    kmpSearch("AABAACAADAABAABA", "AABA");
    return 0;
}

