#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

bool isPalindrome(const string& s) {
    int l = 0, r = s.size() - 1;
    while (l < r) {
        if (s[l++] != s[r--]) return false;
    }
    return true;
}

bool isAnagram(const string& s, const string& t) {
    if (s.size() != t.size()) return false;
    int freq[26] = {0};
    for (char c : s) freq[c-'a']++;
    for (char c : t) freq[c-'a']--;
    for (int x : freq) if (x != 0) return false;
    return true;
}

void charFrequency(const string& s) {
    int freq[26] = {0};
    for (char c : s) freq[c-'a']++;
    for (int i = 0; i < 26; i++)
        if (freq[i]) cout << (char)('a'+i) << ": " << freq[i] << endl;
}

int main() {
    cout << isPalindrome("racecar") << endl;       // 1
    cout << isAnagram("listen", "silent") << endl; // 1
    charFrequency("hello");
    return 0;
}

